   147→// PromptResponsePair represents a user prompt and the assistant's responses.
   148→// Used for extracting all interactions from a transcript.
   149→type PromptResponsePair struct {
   150→	Prompt    string
   151→	Responses []string // Multiple responses can occur between tool calls
   152→	Files     []string
   153→}
   154→
   155→// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
   156→// Returns pairs in chronological order (oldest first).
   157→// Each pair contains the user's prompt, assistant's text response, and files modified.
   158→func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
   159→	var pairs []PromptResponsePair
   160→
   161→	// Find all user prompts (messages with string content, not tool results)
   162→	var userIndices []int
   163→	for i, line := range transcript {
   164→		if line.Type == transcriptTypeUser {
   165→			var msg userMessage
   166→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   167→				continue
   168→			}
   169→			// Only count messages with string content (real user prompts)
   170→			if _, ok := msg.Content.(string); ok {
   171→				userIndices = append(userIndices, i)
   172→			} else if arr, ok := msg.Content.([]interface{}); ok {
   173→				// Check if array has text blocks (also a real user prompt)
   174→				for _, item := range arr {
   175→					if m, ok := item.(map[string]interface{}); ok {
   176→						if m["type"] == contentTypeText {
   177→							userIndices = append(userIndices, i)
   178→							break
   179→						}
   180→					}
   181→				}
   182→			}
   183→		}
   184→	}
   185→
   186→	// For each user prompt, extract the prompt text, following assistant response, and files
   187→	for idx, userIdx := range userIndices {
   188→		// Determine the range for this prompt's conversation
   189→		endIdx := len(transcript)
   190→		if idx < len(userIndices)-1 {
   191→			endIdx = userIndices[idx+1]
   192→		}
   193→
   194→		// Extract prompt text
   195→		prompt := extractUserPromptAt(transcript, userIdx)
   196→		if prompt == "" {
   197→			continue
   198→		}
   199→
   200→		// Extract assistant responses and files from this range
   201→		slice := transcript[userIdx:endIdx]
   202→		responses := extractAssistantResponses(slice)
   203→		files := extractModifiedFiles(slice)
   204→
   205→		pairs = append(pairs, PromptResponsePair{
   206→			Prompt:    prompt,
   207→			Responses: responses,
   208→			Files:     files,
   209→		})
   210→	}
   211→
   212→	return pairs
   213→}
