   252→// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
   253→// A single prompt can trigger multiple assistant responses interspersed with tool calls.
   254→func extractAssistantResponses(transcript []transcriptLine) []string {
   255→	var texts []string
   256→	for _, line := range transcript {
   257→		if line.Type == transcriptTypeAssistant {
   258→			var msg assistantMessage
   259→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   260→				continue
   261→			}
   262→
   263→			for _, block := range msg.Content {
   264→				if block.Type == contentTypeText && block.Text != "" {
   265→					texts = append(texts, block.Text)
   266→				}
   267→			}
   268→		}
   269→	}
   270→	return texts
   271→}
