   273→// extractUserPrompts extracts all user messages from the transcript in order.
   274→// Only considers messages with string content (not tool results).
   275→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   276→func extractUserPrompts(transcript []transcriptLine) []string {
   277→	var prompts []string
   278→	for i := range transcript {
   279→		if transcript[i].Type != transcriptTypeUser {
   280→			continue
   281→		}
   282→		var msg userMessage
   283→		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   284→			continue
   285→		}
   286→
   287→		// Handle string content
   288→		if str, ok := msg.Content.(string); ok {
   289→			prompts = append(prompts, textutil.StripIDEContextTags(str))
   290→			continue
   291→		}
   292→
   293→		// Handle array content (only if it contains text blocks)
   294→		if arr, ok := msg.Content.([]interface{}); ok {
   295→			var texts []string
   296→			for _, item := range arr {
   297→				if m, ok := item.(map[string]interface{}); ok {
   298→					if m["type"] == contentTypeText {
   299→						if text, ok := m["text"].(string); ok {
   300→							texts = append(texts, text)
   301→						}
   302→					}
   303→				}
   304→			}
   305→			if len(texts) > 0 {
   306→				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
   307→			}
   308→		}
   309→	}
   310→	return prompts
   311→}
