   313→// extractLastUserPrompt extracts the last user message from the transcript.
   314→// Only considers messages with string content (not tool results).
   315→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   316→func extractLastUserPrompt(transcript []transcriptLine) string {
   317→	prompts := extractUserPrompts(transcript)
   318→	if len(prompts) == 0 {
   319→		return ""
   320→	}
   321→	return prompts[len(prompts)-1]
