   324→// extractLastAssistantMessage extracts the last text message from the assistant
   325→func extractLastAssistantMessage(transcript []transcriptLine) string {
   326→	for i := len(transcript) - 1; i >= 0; i-- {
   327→		if transcript[i].Type == transcriptTypeAssistant {
   328→			var msg assistantMessage
   329→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   330→				continue
   331→			}
   332→
   333→			for _, block := range msg.Content {
   334→				if block.Type == contentTypeText && block.Text != "" {
   335→					return block.Text
   336→				}
   337→			}
   338→		}
   339→	}
   340→	return ""
   341→}
