   343→// findLastUserUUID finds the UUID of the last user message (that has string content)
   344→func findLastUserUUID(transcript []transcriptLine) string {
   345→	for i := len(transcript) - 1; i >= 0; i-- {
   346→		if transcript[i].Type == transcriptTypeUser {
   347→			var msg userMessage
   348→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   349→				continue
   350→			}
   351→			// Only count messages with string content (not tool results)
   352→			if _, ok := msg.Content.(string); ok {
   353→				return transcript[i].UUID
   354→			}
   355→		}
   356→	}
   357→	return ""
   358→}
