   381→// extractModifiedFiles extracts the list of files modified by tool calls
   382→func extractModifiedFiles(transcript []transcriptLine) []string {
   383→	fileSet := make(map[string]bool)
   384→	var files []string
   385→
   386→	for _, line := range transcript {
   387→		if line.Type == transcriptTypeAssistant {
   388→			var msg assistantMessage
   389→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   390→				continue
   391→			}
   392→
   393→			for _, block := range msg.Content {
   394→				if block.Type == "tool_use" {
   395→					isModifyTool := false
   396→					for _, name := range claudecode.FileModificationTools {
   397→						if block.Name == name {
   398→							isModifyTool = true
   399→							break
   400→						}
   401→					}
   402→
   403→					if isModifyTool {
   404→						var input toolInput
   405→						if err := json.Unmarshal(block.Input, &input); err != nil {
   406→							continue
   407→						}
   408→
   409→						file := input.FilePath
   410→						if file == "" {
   411→							file = input.NotebookPath
   412→						}
   413→
   414→						if file != "" && !fileSet[file] {
   415→							fileSet[file] = true
   416→							files = append(files, file)
   417→						}
   418→					}
   419→				}
   420→			}
   421→		}
   422→	}
   423→
   424→	return files
   425→}
