   529→// writeTranscript writes transcript lines to a file in JSONL format.
   530→func writeTranscript(path string, transcript []transcriptLine) error {
   531→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
   532→	if err != nil {
   533→		return fmt.Errorf("failed to create file: %w", err)
   534→	}
   535→	defer func() { _ = file.Close() }()
   536→
   537→	for _, line := range transcript {
   538→		data, err := json.Marshal(line)
   539→		if err != nil {
   540→			return fmt.Errorf("failed to marshal line: %w", err)
   541→		}
   542→		if _, err := file.Write(data); err != nil {
   543→			return fmt.Errorf("failed to write line: %w", err)
   544→		}
   545→		if _, err := file.WriteString("\n"); err != nil {
   546→			return fmt.Errorf("failed to write newline: %w", err)
   547→		}
   548→	}
   549→
   550→	return nil
   551→}
