package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"entire.io/cli/cmd/entire/cli/checkpoint"
)

// SummaryGenerator generates checkpoint summaries using an LLM.
type SummaryGenerator interface {
	Generate(ctx context.Context, input SummaryInput) (*checkpoint.CheckpointSummary, error)
}

// SummaryInput contains the condensed checkpoint data for summarization.
type SummaryInput struct {
	Entries []TranscriptEntry // Chronological prompt/response/action entries
}

// TranscriptEntry represents one item in the condensed transcript.
type TranscriptEntry struct {
	Type    TranscriptEntryType // user, assistant, tool
	Content string              // Message text or tool description
}

// TranscriptEntryType represents the type of a transcript entry.
type TranscriptEntryType string

const (
	EntryTypeUser      TranscriptEntryType = "user"
	EntryTypeAssistant TranscriptEntryType = "assistant"
	EntryTypeTool      TranscriptEntryType = "tool"
)

// BuildCondensedTranscript extracts a condensed view of the transcript
// containing user prompts, assistant responses, and key tool actions
// in chronological order.
func BuildCondensedTranscript(transcript []transcriptLine) SummaryInput {
	var entries []TranscriptEntry

	for _, line := range transcript {
		switch line.Type {
		case transcriptTypeUser:
			entry := extractUserEntry(line)
			if entry != nil {
				entries = append(entries, *entry)
			}

		case transcriptTypeAssistant:
			assistantEntries := extractAssistantEntries(line)
			entries = append(entries, assistantEntries...)
		}
	}

	return SummaryInput{Entries: entries}
}

// extractUserEntry extracts a user entry from a transcript line.
// Returns nil if the line doesn't contain a user prompt (e.g., tool results).
func extractUserEntry(line transcriptLine) *TranscriptEntry {
	var msg userMessage
	if err := json.Unmarshal(line.Message, &msg); err != nil {
		return nil
	}

	// Handle string content (direct user prompt)
	if str, ok := msg.Content.(string); ok {
		// Strip IDE context tags
		content := stripIDEContextTagsForSummary(str)
		if content == "" {
			return nil
		}
		return &TranscriptEntry{
			Type:    EntryTypeUser,
			Content: content,
		}
	}

	// Handle array content (only if it contains text blocks)
	if arr, ok := msg.Content.([]interface{}); ok {
		var texts []string
		for _, item := range arr {
			if m, ok := item.(map[string]interface{}); ok {
				if m["type"] == contentTypeText {
					if text, ok := m["text"].(string); ok {
						texts = append(texts, text)
					}
				}
			}
		}
		if len(texts) > 0 {
			content := stripIDEContextTagsForSummary(strings.Join(texts, "\n\n"))
			if content == "" {
				return nil
			}
			return &TranscriptEntry{
				Type:    EntryTypeUser,
				Content: content,
			}
		}
	}

	return nil
}

// extractAssistantEntries extracts assistant text and tool entries from a transcript line.
func extractAssistantEntries(line transcriptLine) []TranscriptEntry {
	var msg assistantMessage
	if err := json.Unmarshal(line.Message, &msg); err != nil {
		return nil
	}

	var entries []TranscriptEntry

	for _, block := range msg.Content {
		switch block.Type {
		case contentTypeText:
			if block.Text != "" {
				entries = append(entries, TranscriptEntry{
					Type:    EntryTypeAssistant,
					Content: block.Text,
				})
			}

		case "tool_use":
			entry := extractToolEntry(block)
			if entry != nil {
				entries = append(entries, *entry)
			}
		}
	}

	return entries
}

// extractToolEntry extracts a tool entry from a content block.
func extractToolEntry(block contentBlock) *TranscriptEntry {
	var input toolInput
	_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing

	// Build description from tool input
	detail := input.Description
	if detail == "" {
		detail = input.Command
	}
	if detail == "" {
		detail = input.FilePath
	}
	if detail == "" {
		detail = input.NotebookPath
	}
	if detail == "" {
		detail = input.Pattern
	}

	content := fmt.Sprintf("%s: %s", block.Name, detail)
	return &TranscriptEntry{
		Type:    EntryTypeTool,
		Content: content,
	}
}

// stripIDEContextTagsForSummary removes IDE-injected context tags from content.
// This is a simplified version that removes common tag patterns.
func stripIDEContextTagsForSummary(content string) string {
	// Common IDE context tags to strip
	tags := []string{
		"<ide_opened_file>", "</ide_opened_file>",
		"<ide_visible_files>", "</ide_visible_files>",
		"<ide_selection>", "</ide_selection>",
		"<ide_cursor>", "</ide_cursor>",
	}

	result := content
	for _, tag := range tags {
		result = strings.ReplaceAll(result, tag, "")
	}

	// Also remove content between these tags (including the tags)
	// Use simple string manipulation for common patterns
	result = removeTagContent(result, "<ide_opened_file>", "</ide_opened_file>")
	result = removeTagContent(result, "<ide_visible_files>", "</ide_visible_files>")
	result = removeTagContent(result, "<ide_selection>", "</ide_selection>")

	return strings.TrimSpace(result)
}

// removeTagContent removes content between start and end tags (inclusive).
func removeTagContent(content, startTag, endTag string) string {
	for {
		startIdx := strings.Index(content, startTag)
		if startIdx == -1 {
			break
		}
		endIdx := strings.Index(content[startIdx:], endTag)
		if endIdx == -1 {
			break
		}
		endIdx += startIdx + len(endTag)
		content = content[:startIdx] + content[endIdx:]
	}
	return content
}

// FormatCondensedTranscript formats a SummaryInput into a human-readable string
// suitable for passing to an LLM.
func FormatCondensedTranscript(input SummaryInput) string {
	var sb strings.Builder

	for _, entry := range input.Entries {
		switch entry.Type {
		case EntryTypeUser:
			sb.WriteString("[User] ")
			sb.WriteString(entry.Content)
			sb.WriteString("\n\n")

		case EntryTypeAssistant:
			sb.WriteString("[Assistant] ")
			sb.WriteString(entry.Content)
			sb.WriteString("\n\n")

		case EntryTypeTool:
			sb.WriteString("[Tool] ")
			sb.WriteString(entry.Content)
			sb.WriteString("\n")
		}
	}

	return strings.TrimSpace(sb.String())
}

