   387→// CalculateTotalTokenUsage calculates token usage for a turn, including subagents.
   388→// It parses the main transcript from startLine, extracts spawned agent IDs,
   389→// and calculates their token usage from transcripts in subagentsDir.
   390→func CalculateTotalTokenUsage(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
   391→	// Calculate main transcript usage
   392→	mainUsage, err := CalculateTokenUsageFromFile(transcriptPath, startLine)
   393→	if err != nil {
   394→		return nil, fmt.Errorf("failed to calculate main token usage: %w", err)
   395→	}
   396→
   397→	// Parse the transcript to find spawned agents
   398→	transcript, err := parseTranscriptFromLine(transcriptPath, startLine)
   399→	if err != nil {
   400→		return nil, fmt.Errorf("failed to parse transcript for agent IDs: %w", err)
   401→	}
   402→
   403→	agentIDs := ExtractSpawnedAgentIDs(transcript)
   404→
   405→	// Calculate subagent token usage
   406→	if len(agentIDs) > 0 {
   407→		subagentUsage := &agent.TokenUsage{}
   408→		for agentID := range agentIDs {
   409→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
   410→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
   411→			if err != nil {
   412→				// Agent transcript may not exist yet or may have been cleaned up
   413→				continue
   414→			}
   415→			subagentUsage.InputTokens += agentUsage.InputTokens
   416→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
   417→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
   418→			subagentUsage.OutputTokens += agentUsage.OutputTokens
   419→			subagentUsage.APICallCount += agentUsage.APICallCount
   420→		}
   421→		if subagentUsage.APICallCount > 0 {
   422→			mainUsage.SubagentTokens = subagentUsage
   423→		}
   424→	}
   425→
   426→	return mainUsage, nil
   427→}
